CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapability("sasl")) {
        user->sendNumeric(ERR_SASL_NOCAPABILITY, "SASL authentication not allowed without capability");
        return CMD_FAILURE;
    }

    if (parameters.empty() || parameters[0].empty()) {
        user->sendNumeric(ERR_SASL_MALFORMED, "SASL authentication parameters malformed");
        return CMD_FAILURE;
    }

    if (!user->getSASLAuthenticator()) {
        user->setSASLAuthenticator(new SASLAuthenticator(user));
    }

    SASLAuthenticator* authenticator = user->getSASLAuthenticator();
    if (!authenticator->sendClientMessage(parameters[0])) {
        user->sendNumeric(ERR_SASL_FAIL, "SASL authentication failed");
        delete authenticator;
        user->setSASLAuthenticator(nullptr);
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered())
        return CMD_FAILURE;

    if (!user->hasCap("sasl"))
        return CMD_FAILURE;

    if (parameters.empty() || parameters[0].empty())
        return CMD_FAILURE;

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = std::make_unique<SaslAuthenticator>(parameters[0]);
    } else {
        if (!user->saslAuthenticator->sendClientMessage(user, parameters)) {
            user->sendAnnounce("SASL authentication failed.");
            user->saslAuthenticator.reset();
            return CMD_FAILURE;
        }
    }

    return CMD_FAILURE;
}

