CmdResult handleUnregisteredSASLAuth(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapabilities("sasl")) {
        user->write("ERROR :SASL not supported");
        return CMD_FAILURE;
    }

    if (parameters.empty() || parameters[0].empty()) {
        user->write("ERROR :Invalid SASL authentication format");
        return CMD_FAILURE;
    }

    if (!user->getSASLAuthenticator()) {
        user->setSASLAuthenticator(std::make_unique<SASLAuthenticator>(parameters[0]));
    }

    if (!user->getSASLAuthenticator()->sendClientMessage(user)) {
        user->write("ERROR :SASL authentication failed");
        user->unsetSASLAuthenticator();
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredSaslAuth(const std::vector<std::string>& parameters, User* user) {
    if (user->isRegistered())
        return CMD_FAILURE;

    if (!user->hasCap("sasl"))
        return CMD_FAILURE;

    if (parameters.empty() || parameters[0].empty())
        return CMD_FAILURE;

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = std::make_unique<SaslAuthenticator>(parameters[0]);
    }

    if (!user->saslAuthenticator->sendClientMessage()) {
        user->saslAuthenticator->announceState();
        user->saslAuthenticator.reset();
        return CMD_FAILURE;
    }

    return CMD_FAILURE;
}
